<section class="container detail-section">
  <a class="back-link" href="<?= e(url('events')) ?>">← Вся афиша</a>
  <div class="detail-layout"><div class="detail-main"><div class="detail-art"><img src="<?= e(poster($event)) ?>" alt="" width="900" height="650"><span class="card-category"><?= e($event['category_name']) ?></span></div><div class="eyebrow detail-city"><?= e($event['city']) ?> · <?= e($event['category_name']) ?></div><h1 translate="no"><?= e($event['title']) ?></h1><div class="organizer-line"><span class="avatar"><?= e(mb_substr($organizer, 0, 1)) ?></span><div><small>Организатор</small><strong translate="no"><?= e($organizer) ?></strong></div></div><section class="description-section"><h2>О событии</h2><div class="prose" translate="no"><?= nl2br(e($event['description'])) ?></div></section>
  <section class="comments-section"><div class="section-head"><h2>Обсуждение</h2><span class="count-badge"><?= count($comments) ?></span></div><p class="muted">Задай вопрос или поделись ожиданиями.</p>
    <?php if ($user): ?><form method="post" action="<?= e(url('event', ['id' => $event['id']])) ?>" class="comment-form"><?= csrf_field() ?><input type="hidden" name="action" value="comment_add"><input type="hidden" name="event_id" value="<?= (int)$event['id'] ?>"><label class="sr-only" for="comment-body">Твой комментарий</label><textarea id="comment-body" name="body" placeholder="Что хочешь узнать о событии?" required maxlength="2000" rows="3"><?= e($old['body'] ?? '') ?></textarea><button class="button button-dark button-small" type="submit">Отправить <span>↗</span></button></form><?php else: ?><p class="signin-note"><a href="<?= e(url('login')) ?>">Войди</a>, чтобы присоединиться к обсуждению.</p><?php endif; ?>
    <div class="comments-list"><?php foreach ($comments as $comment): ?><article class="comment"><span class="avatar"><?= e(mb_substr($comment['author'], 0, 1)) ?></span><div><div class="comment-meta"><strong translate="no"><?= e($comment['author']) ?></strong><time><?= e(date_label($comment['created_at'])) ?></time></div><p translate="no"><?= nl2br(e($comment['body'])) ?></p></div></article><?php endforeach; ?><?php if (!$comments): ?><p class="empty-comments">Пока тихо. Начни разговор первым ✳</p><?php endif; ?></div>
  </section></div>
  <aside class="booking-panel"><div class="eyebrow">Встречаемся здесь</div><div class="booking-price"><?= e(money($event['price'])) ?></div><p class="muted booking-explanation"><?= (float)$event['price'] > 0 ? 'Оплата на месте у организатора' : 'Хорошие впечатления — без билета' ?></p><dl class="event-facts"><div><dt>▦ Дата и время</dt><dd><?= e(date_label($event['starts_at'])) ?></dd></div><div><dt>⌖ Место встречи</dt><dd><?= e($event['city']) ?><br><span><?= e($event['venue']) ?></span></dd></div><div><dt>◉ Участники</dt><dd><?= (int)$attendees ?> из <?= (int)$event['capacity'] ?> мест</dd></div></dl><progress class="capacity-track" max="<?= max(1, (int)$event['capacity']) ?>" value="<?= (int)$attendees ?>" aria-label="Занятые места"></progress>
    <?php if (strtotime($event['starts_at']) <= time()): ?><div class="notice notice-neutral">Событие уже состоялось</div>
    <?php elseif ($isRegistered): ?><div class="registered-state">✓ Ты в списке участников!</div><p class="small-text muted">Все детали сохранены в «Моих событиях».</p><form method="post" action="<?= e(url('event', ['id' => $event['id']])) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="booking_cancel"><input type="hidden" name="event_id" value="<?= (int)$event['id'] ?>"><button class="button button-outline full-width" type="submit" data-confirm="Отменить запись на это событие?">Отменить запись</button></form>
    <?php elseif ($attendees >= $event['capacity']): ?><div class="notice notice-neutral">Все места уже заняты</div>
    <?php elseif ($user): ?><form method="post" action="<?= e(url('event', ['id' => $event['id']])) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="booking_add"><input type="hidden" name="event_id" value="<?= (int)$event['id'] ?>"><button class="button button-lime full-width" type="submit">Я иду! <span>↗</span></button></form><p class="small-text muted centered">Запись займёт всего один клик</p>
    <?php else: ?><a class="button button-lime full-width" href="<?= e(url('login')) ?>">Войти и записаться <span>↗</span></a><p class="small-text muted centered">Войди, чтобы забронировать место</p><?php endif; ?>
    <?php if ($user && ((int)$user['id'] === (int)$event['organizer_id'] || ($user['role'] ?? '') === 'admin')): ?><a class="edit-event-link" href="<?= e(url('edit', ['id' => $event['id']])) ?>">Редактировать событие →</a><?php endif; ?>
  </aside></div>
</section>
